t.script:
(function () {
    var form = document.getElementById('bmaglass_momo_start');
    var errorBox = document.getElementById('bmaglass_momo_error');
    var waitingBox = document.getElementById('bmaglass_momo_waiting');
    var landing = document.getElementById('bmaglass_landing_route').value;
    function showError(msg) {
        errorBox.textContent = msg;
        errorBox.style.display = 'block';
    }
    function poll() {
        var url = '/payment/bmaglass/momo/status?tx_id='
            + encodeURIComponent(form.tx_id.value)
            + '&access_token=' + encodeURIComponent(form.access_token.value);
        fetch(url).then(function (r) { return r.json(); }).then(function (data) {
            if (data.state === 'done' || data.state === 'error' || data.state === 'cancel') {
                window.location.href = data.landing_route || landing;
            }
        });
    }
    form.addEventListener('submit', function () {
        errorBox.style.display = 'none';
        var btn = form.querySelector('button[type="submit"]');
        btn.disabled = true;
        var body = new URLSearchParams();
        body.append('tx_id', form.tx_id.value);
        body.append('access_token', form.access_token.value);
        body.append('phone', form.phone.value);
        body.append('operator', form.operator.value);
        fetch('/payment/bmaglass/momo/start', {method: 'POST', body: body})
            .then(function (r) { return r.json(); })
            .then(function (data) {
                if (data.error) {
                    showError(data.message || 'The payment could not be started. Check the number and try again.');
                    btn.disabled = false;
                    return;
                }
                if (data.status === 'successful' || data.state === 'done') {
                    window.location.href = data.landing_route || landing;
                    return;
                }
                form.style.display = 'none';
                waitingBox.style.display = 'block';
                setInterval(poll, 2000);
            })
            .catch(function () {
                showError('Could not reach the shop. Check your connection and try again.');
                btn.disabled = false;
            });
    });
})();
